    ('digital-first', 'ưu tiên nền tảng số', '/ˈdɪdʒɪtəl fɜːrst/', 'The bank follows a digital-first strategy for all services.', 'Ngân hàng theo chiến lược ưu tiên số cho mọi dịch vụ.', 'adjective'),
    ('challenger bank', 'ngân hàng thách thức (đối thủ mới, thuần số)', '/ˈtʃælɪndʒər/', 'Challenger banks compete with traditional lenders on fees.', 'Ngân hàng thách thức cạnh tranh với ngân hàng truyền thống về phí.', 'phrase'),
    ('NFC payment', 'thanh toán bằng công nghệ NFC (chạm gần)', '/ˌen ef ˈsiː/', 'NFC payment lets you pay by holding your phone near the reader.', 'Thanh toán NFC cho phép bạn trả tiền bằng cách đưa điện thoại lại gần máy đọc.', 'phrase'),
    ('digital KYC', 'định danh khách hàng số', '/ˈdɪdʒɪtəl/', 'Digital KYC verifies new users without a branch visit.', 'Định danh khách hàng số xác minh người dùng mới mà không cần đến chi nhánh.', 'phrase'),
    ('open API', 'giao diện lập trình mở', '/ˈoʊpən/', 'Banks publish an open API for developers to build on.', 'Ngân hàng công bố API mở để lập trình viên xây dựng ứng dụng.', 'phrase'),
    ('robo-investing', 'đầu tư tự động bằng thuật toán', '/ˈroʊboʊ ɪnˈvestɪŋ/', 'Robo-investing rebalances your portfolio automatically.', 'Đầu tư tự động cân bằng lại danh mục của bạn một cách tự động.', 'phrase'),
    ('trade finance', 'tài trợ thương mại', '/treɪd/', 'Trade finance helps exporters and importers reduce payment risk in cross-border deals.', 'Tài trợ thương mại giúp nhà xuất khẩu và nhập khẩu giảm rủi ro thanh toán trong giao dịch xuyên biên giới.', 'phrase'),
    ('international trade', 'thương mại quốc tế', '/ˌɪntərˈnæʃnəl/', 'International trade allows countries to exchange goods and services across borders.', 'Thương mại quốc tế cho phép các quốc gia trao đổi hàng hóa và dịch vụ qua biên giới.', 'phrase'),
    ('letter of credit', 'thư tín dụng (L/C)', '/ˈletər/', 'The exporter shipped the goods after receiving the letter of credit.', 'Nhà xuất khẩu giao hàng sau khi nhận được thư tín dụng.', 'phrase'),
    ('L/C', 'thư tín dụng (viết tắt của letter of credit)', NULL, 'The buyer opened an L/C in favour of the seller through his bank.', 'Người mua mở một L/C có lợi cho người bán thông qua ngân hàng của mình.', 'acronym'),
    ('documentary credit', 'tín dụng chứng từ', '/ˌdɒkjuˈmentri/', 'A documentary credit guarantees payment once the required documents are presented.', 'Tín dụng chứng từ bảo đảm thanh toán khi các chứng từ yêu cầu được xuất trình.', 'phrase'),
