    ('revocable letter of credit', 'thư tín dụng hủy ngang', '/ˈrevəkəbl/', 'A revocable letter of credit can be cancelled by the issuing bank at any time.', 'Thư tín dụng hủy ngang có thể bị ngân hàng phát hành hủy bất cứ lúc nào.', 'phrase'),
    ('confirmed letter of credit', 'thư tín dụng có xác nhận', '/kənˈfɜːrmd/', 'A confirmed letter of credit adds a second bank''s payment guarantee.', 'Thư tín dụng có xác nhận bổ sung thêm cam kết thanh toán của một ngân hàng thứ hai.', 'phrase'),
    ('standby letter of credit', 'thư tín dụng dự phòng (SBLC)', '/ˈstændbaɪ/', 'A standby letter of credit is used as a backup if the buyer fails to pay.', 'Thư tín dụng dự phòng được dùng làm phương án dự phòng nếu người mua không thanh toán.', 'phrase'),
    ('SBLC', 'thư tín dụng dự phòng (viết tắt)', NULL, 'The contractor provided an SBLC to secure his performance obligations.', 'Nhà thầu cung cấp một SBLC để bảo đảm nghĩa vụ thực hiện của mình.', 'acronym'),
    ('advising bank', 'ngân hàng thông báo', '/ədˈvaɪzɪŋ/', 'The advising bank notifies the exporter that the credit has been opened.', 'Ngân hàng thông báo báo cho nhà xuất khẩu biết thư tín dụng đã được mở.', 'phrase'),
    ('confirming bank', 'ngân hàng xác nhận', '/kənˈfɜːrmɪŋ/', 'The confirming bank guarantees payment even if the issuing bank defaults.', 'Ngân hàng xác nhận bảo đảm thanh toán ngay cả khi ngân hàng phát hành mất khả năng chi trả.', 'phrase'),
