    ('without recourse', 'miễn truy đòi', '/wɪˈðaʊt/', 'Financing without recourse transfers the default risk to the buyer of the debt.', 'Tài trợ miễn truy đòi chuyển rủi ro vỡ nợ sang bên mua khoản nợ.', 'phrase'),
    ('invoice financing', 'tài trợ hóa đơn', '/ˈɪnvɔɪs/', 'Invoice financing lets a company borrow against its unpaid invoices.', 'Tài trợ hóa đơn cho phép doanh nghiệp vay dựa trên các hóa đơn chưa thanh toán.', 'phrase'),
    ('invoice discounting', 'chiết khấu hóa đơn', '/ˈɪnvɔɪs/', 'Invoice discounting gives the seller early cash while keeping collection in-house.', 'Chiết khấu hóa đơn giúp người bán có tiền sớm trong khi vẫn tự thu hồi công nợ.', 'phrase'),
    ('supply chain finance', 'tài trợ chuỗi cung ứng', '/səˈplaɪ/', 'Supply chain finance lets suppliers get paid early at the buyer''s low borrowing rate.', 'Tài trợ chuỗi cung ứng giúp nhà cung cấp được trả sớm với lãi suất vay thấp của người mua.', 'phrase'),
    ('incoterms', 'điều kiện thương mại quốc tế (Incoterms)', '/ˈɪnkəʊtɜːmz/', 'Incoterms define who pays for shipping, insurance and customs in a sale.', 'Incoterms quy định ai chịu chi phí vận chuyển, bảo hiểm và hải quan trong một giao dịch.', 'noun'),
    ('FOB', 'giao hàng lên tàu (Free On Board)', NULL, 'Under FOB, the seller''s responsibility ends once the goods pass the ship''s rail.', 'Theo điều kiện FOB, trách nhiệm của người bán kết thúc khi hàng qua lan can tàu.', 'acronym'),
    ('CIF', 'tiền hàng, bảo hiểm và cước phí (Cost, Insurance, Freight)', NULL, 'CIF means the seller pays cost, insurance and freight to the destination port.', 'CIF nghĩa là người bán trả tiền hàng, bảo hiểm và cước phí tới cảng đích.', 'acronym'),
    ('CFR', 'tiền hàng và cước phí (Cost and Freight)', NULL, 'Under CFR the seller covers freight but not insurance to the port.', 'Theo điều kiện CFR người bán trả cước phí nhưng không trả bảo hiểm tới cảng.', 'acronym'),
    ('EXW', 'giao tại xưởng (Ex Works)', NULL, 'With EXW the buyer bears all costs and risks from the seller''s premises.', 'Với điều kiện EXW người mua chịu mọi chi phí và rủi ro từ kho của người bán.', 'acronym'),
    ('DAP', 'giao tại nơi đến (Delivered At Place)', NULL, 'Under DAP the seller delivers the goods ready for unloading at the named place.', 'Theo điều kiện DAP người bán giao hàng sẵn sàng để dỡ tại địa điểm chỉ định.', 'acronym'),
    ('DDP', 'giao đã nộp thuế (Delivered Duty Paid)', NULL, 'With DDP the seller clears customs and pays all import duties.', 'Với điều kiện DDP người bán làm thủ tục hải quan và nộp mọi khoản thuế nhập khẩu.', 'acronym'),
    ('bill of lading', 'vận đơn đường biển', '/bɪl/', 'The bill of lading serves as a receipt and a document of title for the cargo.', 'Vận đơn đường biển vừa là biên nhận vừa là chứng từ sở hữu hàng hóa.', 'phrase'),
    ('B/L', 'vận đơn (viết tắt của bill of lading)', NULL, 'The bank released the B/L to the importer after payment.', 'Ngân hàng giao B/L cho nhà nhập khẩu sau khi thanh toán.', 'acronym'),
    ('straight bill of lading', 'vận đơn đích danh', '/streɪt/', 'A straight bill of lading names a specific consignee and is not transferable.', 'Vận đơn đích danh ghi rõ một người nhận cụ thể và không thể chuyển nhượng.', 'phrase'),
    ('order bill of lading', 'vận đơn theo lệnh', '/ˈɔːrdər/', 'An order bill of lading can be transferred by endorsement to another party.', 'Vận đơn theo lệnh có thể chuyển nhượng bằng cách ký hậu cho bên khác.', 'phrase'),
    ('clean bill of lading', 'vận đơn hoàn hảo (sạch)', '/kliːn/', 'A clean bill of lading confirms the goods were received in good condition.', 'Vận đơn hoàn hảo xác nhận hàng hóa được nhận trong tình trạng tốt.', 'phrase'),
    ('air waybill', 'vận đơn hàng không', '/eər/', 'The air waybill accompanies cargo shipped by air freight.', 'Vận đơn hàng không đi kèm hàng hóa vận chuyển bằng đường hàng không.', 'phrase'),
    ('consignee', 'người nhận hàng', '/ˌkɒnsaɪˈniː/', 'The consignee named on the bill of lading collects the goods at the port.', 'Người nhận hàng ghi trên vận đơn nhận hàng tại cảng.', 'noun'),
    ('consignor', 'người gửi hàng', '/kənˈsaɪnər/', 'The consignor is responsible for packing and delivering the goods to the carrier.', 'Người gửi hàng chịu trách nhiệm đóng gói và giao hàng cho người vận chuyển.', 'noun'),
    ('carrier', 'người vận chuyển (hãng vận tải)', '/ˈkæriər/', 'The carrier transports the cargo from the port of loading to the destination.', 'Người vận chuyển vận chuyển hàng hóa từ cảng xếp hàng tới điểm đến.', 'noun'),
    ('freight forwarder', 'đại lý giao nhận vận tải', '/freɪt/', 'The freight forwarder arranges shipping, customs and documentation for exporters.', 'Đại lý giao nhận vận tải sắp xếp vận chuyển, hải quan và chứng từ cho nhà xuất khẩu.', 'phrase'),
    ('shipping documents', 'bộ chứng từ giao hàng', '/ˈʃɪpɪŋ/', 'The bank checks the shipping documents against the letter of credit terms.', 'Ngân hàng kiểm tra bộ chứng từ giao hàng đối chiếu với điều khoản thư tín dụng.', 'phrase'),
    ('commercial invoice', 'hóa đơn thương mại', '/kəˈmɜːrʃl/', 'The commercial invoice lists the goods, quantities and agreed prices.', 'Hóa đơn thương mại liệt kê hàng hóa, số lượng và giá đã thỏa thuận.', 'phrase'),
    ('proforma invoice', 'hóa đơn chiếu lệ', '/prəˈfɔːrmə/', 'The seller sent a proforma invoice so the buyer could arrange payment.', 'Người bán gửi hóa đơn chiếu lệ để người mua sắp xếp thanh toán.', 'phrase'),
    ('packing list', 'phiếu đóng gói', '/ˈpækɪŋ/', 'The packing list details the contents and weight of each carton.', 'Phiếu đóng gói mô tả chi tiết nội dung và trọng lượng của từng thùng hàng.', 'phrase'),
    ('certificate of origin', 'giấy chứng nhận xuất xứ', '/sərˈtɪfɪkət/', 'A certificate of origin proves where the goods were manufactured.', 'Giấy chứng nhận xuất xứ chứng minh nơi hàng hóa được sản xuất.', 'phrase'),
    ('inspection certificate', 'giấy chứng nhận kiểm định', '/ɪnˈspekʃn/', 'An inspection certificate confirms the goods meet the buyer''s quality standards.', 'Giấy chứng nhận kiểm định xác nhận hàng hóa đạt tiêu chuẩn chất lượng của người mua.', 'phrase'),
    ('bill of exchange', 'hối phiếu', '/bɪl/', 'The exporter drew a bill of exchange on the importer for the invoice amount.', 'Nhà xuất khẩu ký phát hối phiếu đòi nhà nhập khẩu theo số tiền hóa đơn.', 'phrase'),
