    ('touch base', 'trao đổi ngắn để cập nhật tình hình', '/tʌtʃ beɪs/', 'Let''s touch base tomorrow about the deployment plan.', 'Ngày mai chúng ta trao đổi ngắn về kế hoạch triển khai nhé.', 'phrase'),
    ('buy-in', 'sự ủng hộ, sự đồng thuận từ các bên', '/ˈbaɪ ɪn/', 'The plan succeeded because we had buy-in from leadership.', 'Kế hoạch thành công vì chúng tôi có sự ủng hộ từ ban lãnh đạo.', 'noun'),
    ('daily standup', 'họp giao ban hằng ngày', '/ˈdeɪli/', 'In the daily standup, each person shares blockers briefly.', 'Trong buổi giao ban hằng ngày, mỗi người chia sẻ vật cản ngắn gọn.', 'phrase'),
    ('status update', 'cập nhật tình trạng công việc', '/ˈsteɪtəs/', 'Please send a status update by end of day.', 'Vui lòng gửi cập nhật tình trạng trước cuối ngày.', 'phrase'),
    ('progress report', 'báo cáo tiến độ', '/ˈprɑːɡres/', 'The weekly progress report keeps clients informed.', 'Báo cáo tiến độ hằng tuần giúp khách hàng nắm thông tin.', 'phrase'),
    ('mitigation plan', 'kế hoạch giảm thiểu rủi ro', '/ˌmɪtɪˈɡeɪʃn/', 'We prepared a mitigation plan in case the vendor was late.', 'Chúng tôi chuẩn bị kế hoạch giảm thiểu phòng khi nhà cung cấp trễ.', 'phrase'),
    ('contingency plan', 'kế hoạch dự phòng', '/kənˈtɪndʒənsi/', 'The contingency plan lets us roll back if the launch fails.', 'Kế hoạch dự phòng cho phép chúng tôi quay lui nếu ra mắt thất bại.', 'phrase'),
    ('go-live', 'đưa vào hoạt động chính thức, ngày lên môi trường thật', '/ˈɡoʊ laɪv/', 'The go-live is scheduled for Monday at 6 a.m.', 'Việc đưa vào hoạt động chính thức được lên lịch 6 giờ sáng thứ Hai.', 'noun'),
    ('cutover', 'chuyển đổi sang hệ thống mới', '/ˈkʌtoʊvər/', 'The cutover to the new system happened over the weekend.', 'Việc chuyển đổi sang hệ thống mới diễn ra vào cuối tuần.', 'noun'),
    ('release candidate', 'bản ứng viên phát hành (RC)', '/rɪˈliːs/', 'The release candidate passed all tests this afternoon.', 'Bản ứng viên phát hành đã vượt qua mọi bài kiểm thử chiều nay.', 'phrase'),
    ('outage', 'sự cố ngừng dịch vụ, mất kết nối', '/ˈaʊtɪdʒ/', 'The outage lasted twenty minutes before service resumed.', 'Sự cố ngừng dịch vụ kéo dài hai mươi phút trước khi khôi phục.', 'noun'),
    ('triage', 'phân loại và ưu tiên xử lý sự cố', '/ˈtriːɑːʒ/', 'The team meets each morning to triage new bugs.', 'Nhóm họp mỗi sáng để phân loại và ưu tiên lỗi mới.', 'noun'),
    ('runbook', 'sổ tay quy trình xử lý sự cố', '/ˈrʌnbʊk/', 'Follow the runbook to restart the failing service.', 'Làm theo sổ tay quy trình để khởi động lại dịch vụ lỗi.', 'noun'),
    ('handoff', 'chuyển giao công việc giữa các ca hoặc nhóm', '/ˈhændɔːf/', 'A clean handoff avoids losing context between shifts.', 'Chuyển giao gọn gàng tránh mất ngữ cảnh giữa các ca.', 'noun'),
    ('scope document', 'tài liệu phạm vi dự án', '/skoʊp/', 'The scope document lists everything included in this release.', 'Tài liệu phạm vi liệt kê mọi thứ nằm trong đợt phát hành này.', 'phrase'),
    ('scope baseline', 'mốc chuẩn phạm vi dự án', '/skoʊp/', 'Any change is measured against the approved scope baseline.', 'Mọi thay đổi được đo so với mốc chuẩn phạm vi đã duyệt.', 'phrase'),
    ('delivery date', 'ngày bàn giao dự kiến', '/dɪˈlɪvəri/', 'The delivery date slipped by a week due to blockers.', 'Ngày bàn giao bị lùi một tuần do các vật cản.', 'phrase'),
    ('lead time', 'thời gian từ khi yêu cầu đến khi hoàn thành', '/liːd taɪm/', 'Reducing lead time helps us respond faster to customers.', 'Giảm thời gian hoàn thành giúp chúng tôi phản hồi khách nhanh hơn.', 'phrase'),
    ('turnaround time', 'thời gian xử lý và trả kết quả', '/ˈtɜːrnəraʊnd/', 'The support team improved its turnaround time to two hours.', 'Nhóm hỗ trợ cải thiện thời gian xử lý xuống còn hai giờ.', 'phrase'),
    ('estimate', 'ước lượng, dự toán thời gian hoặc công sức', '/ˈestɪmət/', 'The estimate for this feature is about three days.', 'Ước lượng cho tính năng này là khoảng ba ngày.', 'noun'),
    ('overrun', 'vượt kế hoạch (thời gian hoặc chi phí)', '/ˌoʊvərˈrʌn/', 'Poor planning caused a budget overrun on the project.', 'Lập kế hoạch kém gây vượt ngân sách cho dự án.', 'noun'),
    ('scope change', 'thay đổi phạm vi', '/skoʊp/', 'A late scope change forced us to reschedule the launch.', 'Một thay đổi phạm vi muộn buộc chúng tôi dời lịch ra mắt.', 'phrase'),
    ('approval', 'sự phê duyệt', '/əˈpruːvl/', 'The budget needs approval from the finance team.', 'Ngân sách cần sự phê duyệt từ nhóm tài chính.', 'noun'),
    ('escalate', 'chuyển vấn đề lên cấp cao hơn để xử lý', '/ˈeskəleɪt/', 'If the vendor doesn''t respond, escalate the issue to me.', 'Nếu nhà cung cấp không phản hồi, hãy chuyển vấn đề lên cho tôi.', 'verb'),
    ('deprioritize', 'hạ mức ưu tiên', '/ˌdiːpraɪˈɔːrətaɪz/', 'We deprioritized minor bugs to focus on the launch.', 'Chúng tôi hạ ưu tiên các lỗi nhỏ để tập trung vào đợt ra mắt.', 'verb'),
    ('scope out', 'xác định và giới hạn phạm vi công việc', '/skoʊp aʊt/', 'Let''s scope out the task before we commit to a deadline.', 'Hãy xác định phạm vi công việc trước khi cam kết hạn chót.', 'phrase'),
    ('handover document', 'tài liệu bàn giao', '/ˈhændoʊvər/', 'She left a thorough handover document for her replacement.', 'Cô ấy để lại tài liệu bàn giao kỹ lưỡng cho người thay thế.', 'phrase'),
    ('onboarding checklist', 'danh sách kiểm tra hội nhập nhân viên mới', '/ˈɑːnbɔːrdɪŋ/', 'The onboarding checklist covers accounts, tools, and access.', 'Danh sách hội nhập bao gồm tài khoản, công cụ và quyền truy cập.', 'phrase')
